def shortestWithKDistinct(nums, k):
    cnt = {}
    distinct = 0
    left = 0
    best = -1
    for right, x in enumerate(nums):
        cnt[x] = cnt.get(x, 0) + 1
        if cnt[x] == 1:
            distinct += 1
        while distinct >= k:
            length = right - left + 1
            if best < 0 or length < best:
                best = length
            y = nums[left]
            cnt[y] -= 1
            if cnt[y] == 0:
                distinct -= 1
            left += 1
    return best
